// Parse context management request
const request = $input.first().json;

// Required fields validation
if (!request.action || !request.agent_id) {
  return [{
    json: {
      error: 'Missing required fields: action, agent_id',
      status: 'invalid'
    }
  }];
}

// Process context request
const contextId = request.context_id || 'default_party_context';
const timestamp = new Date().toISOString();

const contextRequest = {
  ...request,
  context_id: contextId,
  timestamp,
  processed_by: 'shared_context_manager'
};

return [{
  json: contextRequest
}];

// Handle context update
const request = $input.first().json;

if (!request.context_data) {
  return [{
    json: {
      error: 'Context updates require context_data field',
      status: 'invalid'
    }
  }];
}

const updateData = {
  action: 'context_update',
  context_id: request.context_id,
  agent_id: request.agent_id,
  update_type: request.update_type || 'incremental',
  context_data: request.context_data,
  update_metadata: {
    timestamp: request.timestamp,
    priority: request.priority || 'normal',
    affects_agents: request.affects_agents || 'all',
    tags: request.tags || [],
    version: request.version || null
  }
};

return [{
  json: updateData
}];

// Handle context retrieval
const request = $input.first().json;

const retrievalData = {
  action: 'context_retrieval',
  context_id: request.context_id,
  agent_id: request.agent_id,
  retrieval_params: {
    scope: request.scope || 'full',
    filters: request.filters || {},
    include_history: request.include_history || false,
    include_metadata: request.include_metadata !== false,
    version: request.version || 'latest'
  }
};

return [{
  json: retrievalData
}];

// Merge and validate context updates
const update = $input.first().json;

// Get current context state (simulated)
const currentContext = {
  context_id: update.context_id,
  version: 'v1.0.0',
  last_updated: new Date().toISOString(),
  data: {
    party_state: {
      current_location: 'town_square',
      active_quest: 'the_missing_artifact',
      party_mood: 'adventurous',
      time_of_day: 'morning',
      weather: 'clear'
    },
    shared_knowledge: {
      npcs_met: ['elder_thomas', 'merchant_martha'],
      locations_discovered: ['town_square', 'tavern', 'market'],
      items_obtained: ['map', 'torch'],
      clues_found: ['mysterious_symbol']
    },
    agent_states: {
      dungeon_master: { status: 'active', focus: 'plot_development' },
      narrator: { status: 'active', focus: 'storytelling' },
      combat_manager: { status: 'idle', focus: 'monitoring' }
    }
  },
  metadata: {
    update_count: 0,
    last_updated_by: 'system'
  }
};

// Apply update
const updatedContext = applyContextUpdate(currentContext, update);

function applyContextUpdate(current, update) {
  const updated = JSON.parse(JSON.stringify(current));

  // Increment version
  const versionParts = updated.version.split('.');
  versionParts[2] = (parseInt(versionParts[2]) + 1).toString();
  updated.version = versionParts.join('.');

  // Apply data updates
  if (update.context_data) {
    if (update.update_type === 'merge') {
      deepMerge(updated.data, update.context_data);
    } else if (update.update_type === 'replace') {
      updated.data = update.context_data;
    } else {
      // incremental update
      Object.keys(update.context_data).forEach(key => {
        updated.data[key] = update.context_data[key];
      });
    }
  }

  // Update metadata
  updated.last_updated = update.update_metadata.timestamp;
  updated.metadata.last_updated_by = update.agent_id;
  updated.metadata.update_count += 1;

  return updated;
}

function deepMerge(target, source) {
  for (const key in source) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      target[key] = target[key] || {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
}

return [{
  json: {
    action: 'context_updated',
    context_id: update.context_id,
    updated_context: updatedContext,
    update_applied: update
  }
}];

// Retrieve context data
const retrieval = $input.first().json;

// Mock context retrieval (in real system, would query database)
const contextData = {
  context_id: retrieval.context_id,
  version: 'v1.0.0',
  retrieved_at: new Date().toISOString(),
  data: {
    party_state: {
      current_location: 'town_square',
      active_quest: 'the_missing_artifact',
      party_mood: 'adventurous',
      time_of_day: 'morning',
      weather: 'clear'
    },
    shared_knowledge: {
      npcs_met: ['elder_thomas', 'merchant_martha'],
      locations_discovered: ['town_square', 'tavern', 'market'],
      items_obtained: ['map', 'torch'],
      clues_found: ['mysterious_symbol']
    },
    agent_states: {
      dungeon_master: { status: 'active', focus: 'plot_development' },
      narrator: { status: 'active', focus: 'storytelling' },
      combat_manager: { status: 'idle', focus: 'monitoring' }
    }
  },
  metadata: {
    update_count: 15,
    last_updated: new Date().toISOString(),
    last_updated_by: 'narrator',
    tags: ['active_session', 'party_coordination']
  }
};

// Apply filters if specified
let filteredData = contextData.data;
if (retrieval.retrieval_params.filters && Object.keys(retrieval.retrieval_params.filters).length > 0) {
  filteredData = applyFilters(contextData.data, retrieval.retrieval_params.filters);
}

function applyFilters(data, filters) {
  const result = {};

  if (filters.sections) {
    filters.sections.forEach(section => {
      if (data[section]) {
        result[section] = data[section];
      }
    });
  } else {
    return data;
  }

  return result;
}

return [{
  json: {
    action: 'context_retrieved',
    context_id: retrieval.context_id,
    requested_by: retrieval.agent_id,
    context_data: filteredData,
    metadata: {
      version: contextData.version,
      retrieved_at: contextData.retrieved_at,
      filters_applied: retrieval.retrieval_params.filters
    }
  }
}];

// Create context change notifications
const update = $input.first().json;

if (!update.updated_context) {
  return [{
    json: { error: 'No updated context available' }
  }];
}

// Determine which agents need to be notified
const affectedAgents = ['dungeon_master', 'narrator', 'combat_manager', 'scene_coordinator'];
const requestingAgent = update.update_applied.agent_id;

const notifications = affectedAgents
  .filter(agent => agent !== requestingAgent)
  .map(agent => ({
    type: 'context_change_notification',
    to_agent: agent,
    from_agent: 'shared_context_manager',
    data: {
      context_id: update.context_id,
      change_summary: summarizeContextChange(update),
      updated_by: requestingAgent,
      timestamp: update.update_applied.update_metadata.timestamp,
      version: update.updated_context.version
    },
    message: `Shared context updated by ${requestingAgent}\n\nChange: ${summarizeContextChange(update)}\nVersion: ${update.updated_context.version}`
  }));

return notifications.map(notification => ({
  json: notification
}));

function summarizeContextChange(update) {
  const data = update.context_data;
  const changes = [];

  if (data.party_state) {
    changes.push('Party state updated');
  }
  if (data.shared_knowledge) {
    changes.push('Shared knowledge updated');
  }
  if (data.agent_states) {
    changes.push('Agent states updated');
  }

  return changes.length > 0 ? changes.join(', ') : 'Context data updated';
}
